/*
 * Phrase Gen for Max for Live — writes a generated phrase straight into an
 * Ableton Live clip.  Nothing is played: GENERATE edits the clip's notes
 * through the Live API, and the edit is undoable in Live like any other.
 *
 * The engine below is a line-for-line port of the Move plugin's C engine
 * (../dsp/pg_analyzer.c, pg_generator.c, pg_scale.c, pg_rng.h).  C does its
 * arithmetic in single-precision float; every float operation here goes
 * is rounded to float32 (f() below) so that the same seed produces the same phrase as the C
 * code — tests/test_engine.js checks that against tools/pg_ref_dump.c.
 *
 * Classic Max `js` object (ES5): no let/const/arrow functions.
 *
 * Copyright (c) 2026 Hiro Ikezawa.  MIT License (see ../LICENSE).
 */

autowatch = 0;
inlets = 1;
outlets = 1;    /* status text -> [prepend set] -> [comment] */

/* ---- built-in source phrases ------------------------------------------- */

/* GENERATED by build_m4l.py from ../patterns (via tools/pg_ref_dump.c):
 * the six MIDI files after step extraction and C Phrygian quantisation,
 * exactly what the Move plugin builds at load.  [note, velocity, gate%],
 * note -1 = rest. */
var PG_SOURCES = /*@SOURCES*/[[[53,100,92],[65,100,92],[53,100,92],[51,100,92],[94,100,92],[106,100,92],[44,100,92],[51,100,92]],[[60,100,92],[51,100,92],[67,100,92],[94,100,92],[96,100,92],[-1,0,0],[70,100,92],[51,100,92]],[[58,100,92],[61,100,92],[67,100,92],[72,100,92],[75,100,92],[106,100,92],[111,100,92],[43,100,92]],[[58,100,92],[61,100,92],[53,100,92],[70,100,92],[96,100,92],[103,100,92],[55,100,92],[46,100,92]],[[104,100,92],[56,100,92],[79,100,92],[49,100,92],[53,100,92],[67,100,92],[68,100,92],[94,100,92]],[[104,100,92],[103,100,92],[77,100,92],[89,100,92],[79,100,92],[111,100,92],[56,100,92],[36,100,92]]]/*@END*/;

/* ---- constants (pg_pattern.h, pg_analyzer.h, pg_generator.c) ----------- */

/* Max's classic js engine predates Math.fround / Math.imul: polyfill both
 * (Float32Array is old enough to exist there). */
var _f32 = new Float32Array(1);
function f(x) { _f32[0] = x; return _f32[0]; }
function imul(a, b) {
    var ah = (a >>> 16) & 0xffff, al = a & 0xffff;
    var bh = (b >>> 16) & 0xffff, bl = b & 0xffff;
    return ((al * bl) + (((ah * bl + al * bh) << 16) >>> 0)) | 0;
}

var PG_REST = -1;
var PG_GATE_MIN = 5;
var PG_GATE_MAX = 400;
var PG_LENGTH = 8;
var PG_INTERVAL_MAX = 60;
var PG_INTERVAL_BINS = 2 * PG_INTERVAL_MAX + 1;
var PG_OCTAVES = 11;
var PG_MASK_PHRYGIAN = 0x5AB;
var GEN_ATTEMPTS = 4;
var W_SOURCE = f(0.6);
var W_CORPUS = f(1 - W_SOURCE);

function clampi(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
function clampf(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
function zeros(n) { var a = []; for (var i = 0; i < n; i++) a.push(0); return a; }
function trunc(v) { return v < 0 ? Math.ceil(v) : Math.floor(v); }  /* C (int) cast */

/* ---- pattern helpers ---------------------------------------------------- */

function isNote(st) { return st.note >= 0; }

function patFromArray(arr) {
    var steps = [];
    for (var i = 0; i < arr.length; i++)
        steps.push({ note: arr[i][0], vel: arr[i][1], gate: arr[i][2] });
    return { steps: steps, length: arr.length };
}

function patCopy(p) {
    var steps = [];
    for (var i = 0; i < p.steps.length; i++)
        steps.push({ note: p.steps[i].note, vel: p.steps[i].vel, gate: p.steps[i].gate });
    return { steps: steps, length: p.length };
}

function noteCount(p) {
    var n = 0;
    for (var i = 0; i < p.length; i++) if (isNote(p.steps[i])) n++;
    return n;
}

function patEqual(a, b) {
    if (a.length !== b.length) return false;
    for (var i = 0; i < a.length; i++) {
        var x = a.steps[i], y = b.steps[i];
        if (x.note !== y.note) return false;
        if (x.note >= 0 && (x.vel !== y.vel || x.gate !== y.gate)) return false;
    }
    return true;
}

/* ---- RNG (pg_rng.h): xorshift32, bit-exact ------------------------------ */

function Rng(seed) {
    seed = (seed + 0x9E3779B9) >>> 0;
    seed = (seed ^ (seed >>> 16)) >>> 0; seed = imul(seed, 0x85EBCA6B) >>> 0;
    seed = (seed ^ (seed >>> 13)) >>> 0; seed = imul(seed, 0xC2B2AE35) >>> 0;
    seed = (seed ^ (seed >>> 16)) >>> 0;
    this.s = seed ? seed : 0x6D2B79F5;
}
Rng.prototype.next = function () {
    var x = this.s;
    x = (x ^ (x << 13)) >>> 0; x = (x ^ (x >>> 17)) >>> 0; x = (x ^ (x << 5)) >>> 0;
    return (this.s = x);
};
Rng.prototype.float = function () { return f((this.next() >>> 8) * (1 / 16777216)); };
Rng.prototype.range = function (lo, hi) {
    if (hi <= lo) return lo;
    return lo + (this.next() % (hi - lo + 1));
};
Rng.prototype.chance = function (p) { return this.float() < p; };
Rng.prototype.tri = function () { return f(this.float() - this.float()); };
Rng.prototype.weighted = function (w, n) {
    var total = 0, i;
    for (i = 0; i < n; i++) if (w[i] > 0) total = f(total + w[i]);
    if (total <= 0) return -1;
    var x = f(this.float() * total);
    var last = -1;
    for (i = 0; i < n; i++) {
        if (w[i] <= 0) continue;
        last = i;
        if (x < w[i]) return i;
        x = f(x - w[i]);
    }
    return last;
};

/* ---- scale (pg_scale.c) ------------------------------------------------- */

function Scale(root, mask) {
    mask &= 0xFFF;
    if (mask === 0) mask = 1;
    this.root = ((root % 12) + 12) % 12;
    this.mask = mask;
    this.offsets = [];
    for (var i = 0; i < 12; i++) if (mask & (1 << i)) this.offsets.push(i);
    this.degrees = this.offsets.length;
}
Scale.prototype.pc = function (note) { return ((note - this.root) % 12 + 12) % 12; };
Scale.prototype.contains = function (note) {
    if (note < 0 || note > 127) return false;
    return ((this.mask >> this.pc(note)) & 1) === 1;
};
Scale.prototype.quantize = function (note) {
    if (note < 0) note = 0;
    if (note > 127) note = 127;
    for (var d = 0; d <= 12; d++) {
        if (this.contains(note - d)) return note - d;
        if (this.contains(note + d)) return note + d;
    }
    return note;
};
Scale.prototype.degree = function (note) {
    if (!this.contains(note)) return -1;
    var pc = this.pc(note);
    for (var i = 0; i < this.degrees; i++) if (this.offsets[i] === pc) return i;
    return -1;
};
Scale.prototype.shift = function (note, n) {
    note = this.quantize(note);
    var next;
    while (n > 0) {
        next = note + 1;
        while (next <= 127 && !this.contains(next)) next++;
        if (next > 127) break;
        note = next; n--;
    }
    while (n < 0) {
        next = note - 1;
        while (next >= 0 && !this.contains(next)) next--;
        if (next < 0) break;
        note = next; n++;
    }
    return note;
};
Scale.prototype.degreeNear = function (degree, near) {
    if (degree < 0 || degree >= this.degrees) return this.quantize(near);
    var pc = (this.root + this.offsets[degree]) % 12;
    var best = -1, bestDist = 1000;
    for (var n = pc; n <= 127; n += 12) {
        var d = n > near ? n - near : near - n;
        if (d < bestDist) { best = n; bestDist = d; }
    }
    return best;
};

/* ---- analyzer (pg_analyzer.c) ------------------------------------------- */

function normalize(v, n) {
    var t = 0, i;
    for (i = 0; i < n; i++) t = f(t + v[i]);
    if (t <= 0) return;
    for (i = 0; i < n; i++) v[i] = f(v[i] / t);
}

function analyze(pats, scale) {
    var n = pats.length;
    var o = {
        n_patterns: n, length: 0,
        onset_prob: zeros(32), count_mean: 0, count_min: 32, count_max: 0,
        pc_hist: zeros(12), octave_hist: zeros(PG_OCTAVES), note_min: 127, note_max: 0,
        interval_hist: zeros(PG_INTERVAL_BINS), markov: [],
        repeat_rate: 0, up_rate: 0, down_rate: 0, leap_rate: 0, transitions: 0,
        vel_mean: 0, vel_dev: 0, vel_min: 127, vel_max: 0,
        gate_mean: 0, gate_min: PG_GATE_MAX, gate_max: 0
    };
    var notesTotal = 0, velSum = 0, gateSum = 0;
    var onsetN = zeros(32);
    var markovRaw = [], a, b, p, s, i;
    for (a = 0; a < 12; a++) { markovRaw.push(zeros(12)); o.markov.push(zeros(12)); }
    var ups = 0, downs = 0, repeats = 0, leaps = 0;

    for (p = 0; p < n; p++) {
        var pat = pats[p];
        if (pat.length > o.length) o.length = pat.length;
        var count = 0, seq = [];
        for (s = 0; s < pat.length; s++) {
            var st = pat.steps[s];
            if (!isNote(st)) continue;
            seq[count++] = st.note;
            onsetN[s]++;
            o.pc_hist[st.note % 12] = f(o.pc_hist[st.note % 12] + 1);
            o.octave_hist[(st.note / 12) | 0] = f(o.octave_hist[(st.note / 12) | 0] + 1);
            if (st.note < o.note_min) o.note_min = st.note;
            if (st.note > o.note_max) o.note_max = st.note;
            velSum += st.vel; gateSum += st.gate;
            if (st.vel < o.vel_min) o.vel_min = st.vel;
            if (st.vel > o.vel_max) o.vel_max = st.vel;
            if (st.gate < o.gate_min) o.gate_min = st.gate;
            if (st.gate > o.gate_max) o.gate_max = st.gate;
        }
        notesTotal += count;
        if (count < o.count_min) o.count_min = count;
        if (count > o.count_max) o.count_max = count;

        for (i = 0; count > 1 && i < count; i++) {
            var x = seq[i], y = seq[(i + 1) % count];
            var iv = clampi(y - x, -PG_INTERVAL_MAX, PG_INTERVAL_MAX);
            o.interval_hist[iv + PG_INTERVAL_MAX] = f(o.interval_hist[iv + PG_INTERVAL_MAX] + 1);
            if (iv === 0) repeats++; else if (iv > 0) ups++; else downs++;
            if (iv >= 12 || iv <= -12) leaps++;
            o.transitions++;
            var da = scale.degree(x), db = scale.degree(y);
            if (da >= 0 && db >= 0) markovRaw[da][db] = f(markovRaw[da][db] + 1);
        }
    }

    if (n > 0) o.count_mean = f(notesTotal / n);
    for (s = 0; s < 32; s++) o.onset_prob[s] = n > 0 ? f(onsetN[s] / n) : 0;

    if (notesTotal === 0) {
        o.count_min = 0; o.note_min = 48; o.note_max = 72;
        o.vel_min = o.vel_max = 100; o.vel_mean = 100;
        o.gate_min = o.gate_max = 90; o.gate_mean = 90;
        return o;
    }

    normalize(o.pc_hist, 12);
    normalize(o.octave_hist, PG_OCTAVES);
    normalize(o.interval_hist, PG_INTERVAL_BINS);

    var deg = scale.degrees;
    for (a = 0; a < deg; a++) {
        for (b = 0; b < deg; b++) {
            var dist = a > b ? a - b : b - a;
            if (dist > ((deg / 2) | 0)) dist = deg - dist;
            var smooth = dist <= 1 ? f(0.15) : f(0.05);
            o.markov[a][b] = f(markovRaw[a][b] + smooth);
        }
        normalize(o.markov[a], deg);
    }

    if (o.transitions > 0) {
        var t = o.transitions;
        o.repeat_rate = f(repeats / t); o.up_rate = f(ups / t);
        o.down_rate = f(downs / t); o.leap_rate = f(leaps / t);
    }

    o.vel_mean = f(velSum / notesTotal);
    o.gate_mean = f(gateSum / notesTotal);
    var dev = 0;
    for (p = 0; p < n; p++) {
        for (s = 0; s < pats[p].length; s++) {
            var st2 = pats[p].steps[s];
            if (!isNote(st2)) continue;
            var d = f(st2.vel - o.vel_mean);
            dev = f(dev + (d < 0 ? -d : d));
        }
    }
    o.vel_dev = f(dev / notesTotal);
    return o;
}

/* ---- generator (pg_generator.c) ----------------------------------------- */

function mix(s, c) { return f(f(W_SOURCE * s) + f(W_CORPUS * c)); }

function fitNote(g, note) {
    if (g.hi - g.lo >= 11) {
        while (note > g.hi) note -= 12;
        while (note < g.lo) note += 12;
    }
    return g.scale.quantize(clampi(note, 0, 127));
}

function prevNote(p, step) {
    for (var k = 1; k <= p.length; k++) {
        var s = ((step - k) % p.length + p.length) % p.length;
        if (s !== step && isNote(p.steps[s])) return p.steps[s].note;
    }
    return -1;
}

function sampleFreshNote(g) {
    var pc = [], oct = [], i;
    for (i = 0; i < 12; i++) pc.push(mix(g.S.pc_hist[i], g.C.pc_hist[i]));
    for (i = 0; i < PG_OCTAVES; i++) oct.push(mix(g.S.octave_hist[i], g.C.octave_hist[i]));
    var c = g.rng.weighted(pc, 12);
    var o = g.rng.weighted(oct, PG_OCTAVES);
    if (c < 0) c = g.scale.root;
    if (o < 0) o = 5;
    return fitNote(g, o * 12 + c);
}

function markovNext(g, prev) {
    if (prev < 0) return sampleFreshNote(g);
    var deg = g.scale.degree(g.scale.quantize(prev));
    var n = g.scale.degrees, row = [], b, i;
    for (b = 0; b < n; b++) row.push(mix(g.S.markov[deg][b], g.C.markov[deg][b]));
    var nextDeg = g.rng.weighted(row, n);
    var iv = [];
    for (i = 0; i < PG_INTERVAL_BINS; i++) iv.push(mix(g.S.interval_hist[i], g.C.interval_hist[i]));
    var bin = g.rng.weighted(iv, PG_INTERVAL_BINS);
    var target = prev + (bin >= 0 ? bin - PG_INTERVAL_MAX : 0);
    return fitNote(g, g.scale.degreeNear(nextDeg, target));
}

function sampleVelocity(g) {
    var spread = f(f(g.S.vel_dev + 4) + f(8 * g.mut));
    var v = f(g.S.vel_mean + f(g.rng.tri() * spread));
    return clampi(trunc(f(v + 0.5)), 1, 127);
}

function sampleGate(g) {
    return clampi(trunc(f(g.S.gate_mean + 0.5)), PG_GATE_MIN, PG_GATE_MAX);
}

function stageRhythm(g, out, orig) {
    var L = out.length, onset = [], s, w;
    for (s = 0; s < L; s++) onset.push(f(f(0.5 * g.S.onset_prob[s]) + f(0.5 * g.C.onset_prob[s])));

    var nSrc = noteCount(out);
    var dmax = trunc(f(f(g.mut * 2) + 0.5));
    var lo = nSrc - dmax < 1 ? 1 : nSrc - dmax;
    var hi = nSrc + dmax > L ? L : nSrc + dmax;
    var densest = g.C.count_max + 1;
    if (hi > densest && densest >= nSrc) hi = densest;
    var target = clampi(nSrc + g.rng.range(-dmax, dmax) | 0, lo, hi);
    if (g.noRests) target = L;

    var count = nSrc;
    while (count > target) {
        w = [];
        for (s = 0; s < L; s++) w.push(isNote(out.steps[s]) ? f(f(1.05) - onset[s]) : 0);
        s = g.rng.weighted(w, L);
        if (s < 0) break;
        out.steps[s].note = PG_REST; orig[s] = -1; count--;
    }
    while (count < target) {
        w = [];
        for (s = 0; s < L; s++) w.push(isNote(out.steps[s]) ? 0 : f(onset[s] + f(0.05)));
        s = g.rng.weighted(w, L);
        if (s < 0) break;
        out.steps[s].note = markovNext(g, prevNote(out, s));
        out.steps[s].vel = sampleVelocity(g);
        out.steps[s].gate = sampleGate(g);
        orig[s] = -2; count++;
    }

    for (s = 0; s < L; s++) {
        if (orig[s] < 0 || !isNote(out.steps[s])) continue;
        if (!g.rng.chance(f(f(g.mut * f(0.15)) * f(f(1.1) - g.C.onset_prob[s])))) continue;
        var left = (s + L - 1) % L, right = (s + 1) % L;
        var dw = [
            isNote(out.steps[left]) ? 0 : f(onset[left] + f(0.05)),
            isNote(out.steps[right]) ? 0 : f(onset[right] + f(0.05))
        ];
        var pick = g.rng.weighted(dw, 2);
        if (pick < 0) continue;
        var d = pick === 0 ? left : right;
        out.steps[d] = { note: out.steps[s].note, vel: out.steps[s].vel, gate: out.steps[s].gate };
        orig[d] = orig[s];
        out.steps[s].note = PG_REST; orig[s] = -1;
        if (d === right) s++;
    }
}

function fillRests(g, p) {
    for (var s = 0; s < p.length; s++) {
        var st = p.steps[s];
        if (isNote(st)) continue;
        st.note = markovNext(g, prevNote(p, s));
        st.vel = sampleVelocity(g);
        st.gate = sampleGate(g);
    }
}

var SPAN_W = [f(0.55), f(0.30), f(0.15)];

function opShift(g, note) {
    var n = g.rng.weighted(SPAN_W, 3) + 1;
    var up = mix(g.S.up_rate, g.C.up_rate);
    var dn = mix(g.S.down_rate, g.C.down_rate);
    var pUp = f(up + dn) > 0 ? f(up / f(up + dn)) : f(0.5);
    return fitNote(g, g.scale.shift(note, g.rng.chance(pUp) ? n : -n));
}

function opOctave(g, note) {
    var cur = (note / 12) | 0, w = [];
    for (var o = 0; o < PG_OCTAVES; o++) {
        var d = o > cur ? o - cur : cur - o;
        var near = d === 1 ? 1 : d === 2 ? f(0.5) : f(0.15);
        var cand = note + 12 * (o - cur);
        w.push((o === cur || cand < g.lo || cand > g.hi) ? 0
            : f(near * f(f(f(0.05) + f(W_SOURCE * g.S.octave_hist[o])) + f(W_CORPUS * g.C.octave_hist[o]))));
    }
    var pick = g.rng.weighted(w, PG_OCTAVES);
    if (pick < 0) pick = (note + 12 <= 127) ? cur + 1 : cur - 1;
    return fitNote(g, note + 12 * (pick - cur));
}

function stagePitch(g, out, orig) {
    var pPitch = f(f(0.20) + f(f(0.60) * g.mut));
    var leap = mix(g.S.leap_rate, g.C.leap_rate);
    var rep = mix(g.S.repeat_rate, g.C.repeat_rate);
    for (var s = 0; s < out.length; s++) {
        var st = out.steps[s];
        if (!isNote(st) || orig[s] < 0) continue;
        if (!g.rng.chance(pPitch)) continue;
        var prev = prevNote(out, s);
        var w = [
            f(0.40),
            f(f(0.10) + f(f(0.35) * leap)),
            (prev >= 0 && prev !== st.note) ? f(f(0.04) + f(f(0.60) * rep)) : 0,
            f(0.25)
        ];
        var op = g.rng.weighted(w, 4);
        var note = st.note;
        if (op === 0) note = opShift(g, note);
        else if (op === 1) note = opOctave(g, note);
        else if (op === 2) note = prev;
        else if (op === 3) note = markovNext(g, prev);
        if (note === st.note) note = fitNote(g, g.scale.shift(note, g.rng.chance(f(0.5)) ? 1 : -1));
        st.note = note;
    }
}

var GATE_PCT = [50, 75, 125, 150, 200];
var GATE_W = [f(0.25), f(0.30), f(0.20), f(0.15), f(0.10)];

function stageDynamics(g, out, orig) {
    var pVel = f(f(0.30) + f(f(0.50) * g.mut));
    var span = f(3 + f(14 * g.mut));
    var vmin = clampi(g.C.vel_min - 24, 1, 127);
    var vmax = clampi(g.C.vel_max + 20, vmin, 127);
    var pGate = f(f(0.35) * g.mut);
    var gmin = clampi((g.C.gate_min / 2) | 0, PG_GATE_MIN, PG_GATE_MAX);
    var gmax = clampi(g.C.gate_max * 2, gmin, PG_GATE_MAX);

    for (var s = 0; s < out.length; s++) {
        var st = out.steps[s];
        if (!isNote(st)) continue;
        if (orig[s] >= 0 && g.rng.chance(pVel)) {
            var v = f(st.vel + f(g.rng.tri() * span));
            st.vel = clampi(trunc(f(v + (v >= 0 ? 0.5 : -0.5))), vmin, vmax);
        } else {
            st.vel = clampi(st.vel, vmin, vmax);
        }
        if (g.rng.chance(pGate)) {
            var k = g.rng.weighted(GATE_W, 5);
            st.gate = clampi(((st.gate * GATE_PCT[k]) / 100) | 0, gmin, gmax);
        }
    }
}

function quantizeAll(g, p) {
    for (var s = 0; s < p.length; s++) {
        var st = p.steps[s];
        if (!isNote(st)) continue;
        st.note = g.scale.quantize(st.note);
        if (st.vel < 1) st.vel = 1;
        st.gate = clampi(st.gate, PG_GATE_MIN, PG_GATE_MAX);
    }
}

function origFrom(src) {
    var orig = [];
    for (var s = 0; s < 32; s++) orig.push(s < src.length && isNote(src.steps[s]) ? s : -1);
    return orig;
}

/* model: {sources, stats, corpus, scale}; params: {mutation 0..1, source,
 * avoidSource, allowRests}.  Returns {source, pattern}. */
function generate(m, params, rng, avoid) {
    var n = m.sources.length;
    var srcIdx;
    if (params.source >= 0 && params.source < n) srcIdx = params.source;
    else {
        srcIdx = rng.range(0, n - 1);
        if (srcIdx === params.avoidSource && n > 1) srcIdx = rng.range(0, n - 1);
    }
    var g = {
        S: m.stats[srcIdx], C: m.corpus, scale: m.scale, rng: rng,
        mut: clampf(f(params.mutation), 0, 1),
        lo: m.corpus.note_min, hi: m.corpus.note_max,
        noRests: !params.allowRests
    };

    var src = patCopy(m.sources[srcIdx]);
    if (g.noRests) fillRests(g, src);
    quantizeAll(g, src);
    var out, orig;

    for (var attempt = 0; attempt < GEN_ATTEMPTS; attempt++) {
        out = patCopy(src);
        orig = origFrom(src);
        if (g.mut <= 0) break;
        stageRhythm(g, out, orig);
        stagePitch(g, out, orig);
        stageDynamics(g, out, orig);
        quantizeAll(g, out);
        if (noteCount(out) === 0) continue;
        if (patEqual(out, src)) continue;
        if (avoid && patEqual(out, avoid)) continue;
        break;
    }

    if (g.mut > 0 && (patEqual(out, src) || (avoid && patEqual(out, avoid)) || noteCount(out) === 0)) {
        out = patCopy(src);
        var w = [];
        for (var s = 0; s < out.length; s++) w.push(isNote(out.steps[s]) ? 1 : 0);
        var pick = rng.weighted(w, out.length);
        if (pick >= 0) out.steps[pick].note = fitNote(g, g.scale.shift(out.steps[pick].note, rng.chance(f(0.5)) ? 1 : -1));
    }
    return { source: srcIdx, pattern: out };
}

function buildModel(sourceArrays) {
    var scale = new Scale(0, PG_MASK_PHRYGIAN);
    var sources = [], stats = [], i;
    for (i = 0; i < sourceArrays.length; i++) sources.push(patFromArray(sourceArrays[i]));
    for (i = 0; i < sources.length; i++) stats.push(analyze([sources[i]], scale));
    return { sources: sources, stats: stats, corpus: analyze(sources, scale), scale: scale };
}

/* ---- device state ------------------------------------------------------- */

var LENGTH_BEATS = [2, 4, 8, 16];          /* Length menu: 8 steps, 1/2/4 bars */
var LENGTH_NAMES = ["8 steps", "1 bar", "2 bars", "4 bars"];

var model = null;
var rng = null;
var mutation = 50;          /* percent */
var sourceSel = -1;         /* -1 random, else index */
var lengthSel = 0;
var lastPattern = null;
var lastSource = -1;

function ensureEngine() {
    if (!model) model = buildModel(PG_SOURCES);
    if (!rng) rng = new Rng((new Date().getTime() ^ 0x5A17C0DE) >>> 0);
}

/* ---- Max inlet messages ------------------------------------------------- */

function setmutation(v) { mutation = clampi(Math.round(v), 0, 100); }
function setsource(v) {           /* menu index: 0 = random, 1..N = source */
    v = Math.round(v);
    sourceSel = (v <= 0 || v > PG_SOURCES.length) ? -1 : v - 1;
}
function setlength(v) { lengthSel = clampi(Math.round(v), 0, LENGTH_BEATS.length - 1); }

function status(text) { outlet(0, text); }

function bang() { generateclip(); }
function msg_int(v) { if (v) generateclip(); }
function msg_float(v) { if (v) generateclip(); }

/* Phrase -> Live note dictionaries, the 8 steps repeated to fill `beats`. */
function phraseNotes(pat, beats) {
    var notes = [];
    var stepLen = 0.25;
    var phraseBeats = pat.length * stepLen;
    for (var off = 0; off + 1e-9 < beats; off += phraseBeats) {
        for (var s = 0; s < pat.length; s++) {
            var st = pat.steps[s];
            if (!isNote(st)) continue;
            var start = off + s * stepLen;
            if (start + 1e-9 >= beats) break;
            notes.push({
                pitch: st.note,
                start_time: start,
                duration: st.gate / 100 * stepLen,
                velocity: st.vel,
                mute: 0
            });
        }
    }
    return notes;
}

function apiValid(api) { return api && api.id && String(api.id) !== "0"; }

function getNum(api, prop) {
    var v = api.get(prop);
    return (v instanceof Array) ? Number(v[0]) : Number(v);
}

function arrangerVisible() {
    var view = new LiveAPI("live_app view");
    if (!apiValid(view)) return false;
    var r = view.call("is_view_visible", "Arranger");
    return Number(r instanceof Array ? r[0] : r) === 1;
}

/* Which clip to write.
 *   Arrangement view: the clip shown in the clip detail view.
 *   Session view: the selected clip slot -- its clip, or, when the slot is
 *   empty and its track takes MIDI, a new clip created there.
 * Returns {clip, created, arrangement} or {error}. */
function findTargetClip(createBeats) {
    if (arrangerVisible()) {
        var detail = new LiveAPI("live_set view detail_clip");
        if (apiValid(detail)) return { clip: detail, created: false, arrangement: true };
        return { error: "Select a MIDI clip in the Arrangement" };
    }
    var slot = new LiveAPI("live_set view highlighted_clip_slot");
    if (!apiValid(slot)) return { error: "Select a clip slot" };
    if (getNum(slot, "has_clip")) {
        var c = new LiveAPI(slot.unquotedpath + " clip");
        if (apiValid(c)) return { clip: c, created: false, arrangement: false };
        return { error: "Could not read the selected clip" };
    }
    var track = new LiveAPI(slot.unquotedpath.replace(/ clip_slots \d+$/, ""));
    if (!apiValid(track) || !getNum(track, "has_midi_input"))
        return { error: "Selected slot is not on a MIDI track" };
    slot.call("create_clip", createBeats);
    var nc = new LiveAPI(slot.unquotedpath + " clip");
    if (apiValid(nc)) return { clip: nc, created: true, arrangement: false };
    return { error: "Could not create a clip" };
}

/* Live 11+ note API.  Every existing note in the clip is replaced. */
function replaceNotes(clip, notes) {
    clip.call("remove_notes_extended", 0, 128, -16384, 32768);
    if (notes.length) clip.call("add_new_notes", { notes: notes });
}

function generateclip() {
    ensureEngine();
    var target = findTargetClip(LENGTH_BEATS[lengthSel]);
    if (target.error) { status(target.error); return; }
    var clip = target.clip;
    if (!getNum(clip, "is_midi_clip")) { status("That is an audio clip - pick a MIDI clip"); return; }

    var res = generate(model, {
        mutation: mutation / 100, source: sourceSel,
        avoidSource: lastSource, allowRests: false
    }, rng, lastPattern);
    lastPattern = res.pattern;
    lastSource = res.source;

    /* Session: the phrase is repeated to the Length menu and the clip's loop
     * is set to exactly that span.  Arrangement: the clip keeps its length
     * and position; the phrase is repeated across its loop. */
    var start = getNum(clip, "loop_start");
    var beats, label;
    if (target.arrangement) {
        beats = Math.max(getNum(clip, "loop_end") - start, 0.25);
        label = beats + " beats";
    } else {
        beats = LENGTH_BEATS[lengthSel];
        label = LENGTH_NAMES[lengthSel];
    }
    var notes = phraseNotes(res.pattern, beats);
    for (var i = 0; i < notes.length; i++) notes[i].start_time += start;
    replaceNotes(clip, notes);
    if (!target.arrangement) {
        if (getNum(clip, "loop_end") < start + beats) {   /* grow end first, so end > start stays true */
            clip.set("end_marker", start + beats);
            clip.set("loop_end", start + beats);
        } else {
            clip.set("loop_end", start + beats);
            clip.set("end_marker", start + beats);
        }
        clip.set("name", "PG " + (res.source + 1));
    }
    status((target.created ? "New clip: " : "Wrote: ") + label +
           ", source " + (res.source + 1) + ", mutation " + mutation + "%");
}

/* ---- node test hook ----------------------------------------------------- */

if (typeof module !== "undefined" && module.exports) {
    module.exports = {
        Rng: Rng, Scale: Scale, analyze: analyze, generate: generate,
        buildModel: buildModel, phraseNotes: phraseNotes, PG_SOURCES: PG_SOURCES
    };
}
